steps.body:
A plain `T` could be any type at all, so inside the function TypeScript only allows what works for every type. Reading `length` on it is an error (TS2339):

```typescript error
function longest<T>(a: T, b: T): T {
  return b.length > a.length ? b : a;
}

console.log(longest("fig", "kiwi"));
```

`T extends { length: number }` is a constraint: `T` may be any type that has at least a numeric `length`. Now the body can read `length`, and every call must pass values that have one, like strings or arrays:

```typescript
function longest<T extends { length: number }>(a: T, b: T): T {
  return b.length > a.length ? b : a;
}

const tags = longest(["new"], ["sale", "gift"]);
//    ^? const tags: string[]
console.log(tags.join(", ")); // sale, gift
```

The return type is still `T`, so you get back the type you passed in, here a `string[]` you can `join`, not just something with a `length`. That's the reason to constrain a type parameter instead of typing the parameters as `{ length: number }`.

examples.code:
function longest<T extends { length: number }>(a: T, b: T): T {
  return b.length > a.length ? b : a;
}

const mug = { name: "Mug", description: "Stoneware, holds 350 ml" };
const label = longest(mug.name, mug.description);
//    ^? const label: string
console.log(label.toUpperCase());

const anaQuizzes = [72, 85];
const benQuizzes = [64, 91, 78];
const moreQuizzes = longest(anaQuizzes, benQuizzes);
//    ^? const moreQuizzes: number[]
console.log(`${moreQuizzes.length} quizzes, best ${Math.max(...moreQuizzes)}`);

type Product = { id: string; name: string; priceCents: number };
type Customer = { id: string; email: string };

function byId<T extends { id: string }>(items: readonly T[], id: string): T | undefined {
  return items.find((item) => item.id === id);
}

const products: Product[] = [
  { id: "p1", name: "Mug", priceCents: 1299 },
  { id: "p2", name: "Kettle", priceCents: 3450 },
];
const customers: Customer[] = [{ id: "c1", email: "ada@example.com" }];

const kettle = byId(products, "p2");
//    ^? const kettle: Product | undefined
const ada = byId(customers, "c1");
//    ^? const ada: Customer | undefined

console.log(kettle ? `${kettle.name}: $${(kettle.priceCents / 100).toFixed(2)}` : "no product");
console.log(ada?.email ?? "no customer");
console.log(byId(products, "p9")?.name ?? "no product");

function byId<T extends { id: string }>(items: readonly T[], id: string): T | undefined {
  return items.find((item) => item.id === id);
}

const tags = [{ label: "sale" }, { label: "new" }];
console.log(byId(tags, "sale"));

examples.explanation:
The items of `tags` are `{ label: string; }`, with no `id`, so they don't meet the constraint. The call is rejected before anything runs: the first line says the argument doesn't fit `readonly { id: string; }[]`, and the indented line names the missing property. An `id` of the wrong type fails too:

```typescript error
function byId<T extends { id: string }>(items: readonly T[], id: string): T | undefined {
  return items.find((item) => item.id === id);
}

console.log(byId([{ id: 7, label: "sale" }], "7"));
```

Here the check reports TS2322, `Type 'number' is not assignable to type 'string'`, at the `id`. Give every tag an `id` that's a string, and both calls compile.

