type Employee = { name: string; team: string };
type Product = { name: string; priceCents: number };

export function sortByName<T extends { name: string }>(xs: readonly T[]): T[] {
  return xs.toSorted((a, b) => a.name.localeCompare(b.name));
}

const employees: Employee[] = [
  { name: "Caro", team: "support" },
  { name: "Ana", team: "design" },
  { name: "Ben", team: "sales" },
];
const products: Product[] = [
  { name: "Teapot", priceCents: 2100 },
  { name: "Kettle", priceCents: 3450 },
  { name: "Mug", priceCents: 1299 },
];

for (const e of sortByName(employees)) {
  console.log(`${e.name} (${e.team})`);
}
for (const p of sortByName(products)) {
  console.log(`${p.name}: $${(p.priceCents / 100).toFixed(2)}`);
}

steps.body:
`keyof` turns an object type's keys into a union of string literal types. Indexed access, `User["email"]`, is the type of one property:

```typescript types
type User = { id: number; name: string; email: string };

type UserKey = keyof User;
//   ^? type UserKey = keyof User
type Email = User["email"];
//   ^? type Email = string
```

`keyof User` means `"id" | "name" | "email"`, and the editor shows it by that short name.

A generic function can use both. `K extends keyof T` says `K` must be one of `T`'s keys, and a return type of `T[K]` is the type stored under that key. Each call infers `K` from the key you pass, so the result has exactly that property's type:

```typescript
function getProp<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}

const mug = { sku: "MUG-01", stock: 4 };
console.log(getProp(mug, "stock") + 1); // 5
```

A key the object doesn't have is a type error, so a typo can't slip through to runtime.

examples.code:
type User = { id: number; name: string; email: string };

type UserKey = keyof User;
//   ^? type UserKey = keyof User
type Email = User["email"];
//   ^? type Email = string

const ada: User = { id: 1, name: "Ada", email: "ada@example.com" };
const fields: UserKey[] = ["name", "email"];
for (const field of fields) {
  const value = ada[field];
  //    ^? const value: string | number
  console.log(`${field}: ${value}`);
}

const contact: Email = ada.email;
console.log(`Contact: ${contact}`);

examples.explanation:
`UserKey` is `keyof User`, the union `"id" | "name" | "email"`, so `fields` may only hold those three strings. Reading `ada[field]` with a key that could be any of them gives the union of their property types, `string | number`, as the bubble shows. `User["email"]` is `string`, the type of that one property, and it stays in step with `User`: change `email`'s type there, and `Email` changes with it. A string that isn't a key is rejected:

```typescript error
type User = { id: number; name: string; email: string };
type UserKey = keyof User;

const field: UserKey = "phone";
console.log(field);
```

The check reports TS2322, `Type '"phone"' is not assignable to type 'keyof User'`.

examples.code:
function getProp<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}

type User = { id: number; name: string; admin: boolean };
const grace: User = { id: 2, name: "Grace", admin: true };

const userName = getProp(grace, "name");
//    ^? const userName: string
const isAdmin = getProp(grace, "admin");
//    ^? const isAdmin: boolean

console.log(userName.toUpperCase());
console.log(isAdmin ? "Can manage users" : "Read only");

examples.explanation:
Each call infers `T` from the object and `K` from the key, as its literal type. In the first call `K` is `"name"`, so the result is `User["name"]`, a `string`. In the second `K` is `"admin"`, and the result is a `boolean`. That's what the separate `K` buys you. Typed as `(obj: T, key: keyof T): T[keyof T]`, every call would return `string | number | boolean`, and you'd have to narrow each result. A key the object doesn't have fails to compile, and the message lists the keys it does have:

```typescript error
function getProp<T, K extends keyof T>(obj: T, key: K): T[K] {
  return obj[key];
}

const grace = { id: 2, name: "Grace", admin: true };
console.log(getProp(grace, "email"));
```

examples.code:
function pluck<T, K extends keyof T>(xs: readonly T[], key: K): T[K][] {
  return xs.map((x) => x[key]);
}

type Order = { id: string; customer: string; totalCents: number };

const orders: Order[] = [
  { id: "o1", customer: "Ada", totalCents: 1299 },
  { id: "o2", customer: "Ben", totalCents: 4500 },
  { id: "o3", customer: "Ada", totalCents: 800 },
];

const ids = pluck(orders, "id");
//    ^? const ids: string[]
const totals = pluck(orders, "totalCents");
//    ^? const totals: number[]

console.log(ids.join(", "));
console.log(`Largest: ${Math.max(...totals)} cents`);
console.log(`Customers: ${pluck(orders, "customer").join(", ")}`);

