export type Product = { sku: string; name: string; priceCents: number };

export const products: Product[] = [
  { sku: "MUG-01", name: "Mug", priceCents: 1299 },
  { sku: "KET-02", name: "Kettle", priceCents: 3450 },
  { sku: "TEA-03", name: "Teapot", priceCents: 2000 },
];

export function column<T, K extends keyof T>(rows: readonly T[], key: K): T[K][] {
  return rows.map((row) => row[key]);
}

console.log(column(products, "name").join(", "));
const totalCents = column(products, "priceCents").reduce((sum, cents) => sum + cents, 0);
console.log(`Total: $${(totalCents / 100).toFixed(2)}`);

