type Settings = { port: number; host: string; debug: boolean };
const settings: Settings = { port: 8080, host: "localhost", debug: false };

function getSetting(key: "port"): number;
function getSetting(key: "host"): string;
function getSetting(key: "port" | "host"): number | string {
  return settings[key];
}

function setting<K extends keyof Settings>(key: K): Settings[K] {
  return settings[key];
}

const port = getSetting("port");
//    ^? const port: number
const host = setting("host");
//    ^? const host: string
const debug = setting("debug");
//    ^? const debug: boolean

console.log(`${host}:${port}, debug ${debug ? "on" : "off"}`);

