export function select<const T extends readonly string[]>(
  options: T,
  initial: NoInfer<T[number]>,
): { options: T; selected: T[number] } {
  return { options, selected: initial };
}

const size = select(["s", "m", "l"], "m");
console.log(`Size: ${size.selected} of ${size.options.join(", ")}`);
const color = select(["red", "green", "blue"], "green");
console.log(`Color: ${color.selected} of ${color.options.join(", ")}`);
